#!/usr/bin/env python3
"""Emit bounded initial-bin certificates against the pinned while_min loader view."""
import argparse
import re
from pathlib import Path
from boot_certificate import emit_finite_family

ROOT = Path(__file__).resolve().parents[1]


def output():
    bins = int(re.search(r'^def numBins : Nat := (\d+)$',
                        (ROOT / 'Vsa/Sim/DlHeap.lean').read_text(), re.M).group(1))
    out = ['import OCaml.Vm.Boot.Startup.AllocatorBootstrap', '',
           '/-! GENERATED by scripts/gen_boot_allocator.py. Bounded loader reads; no run evaluation. -/',
           'namespace OCaml.Vm.Boot.Startup',
           'open Vsa.Sim Vsa.Sim.Boot Vsa.Sim.DlHeap', '']
    for name, address, value in [('top', 'topAddr', 'avAddr'), ('binblocks', 'binblocksAddr', '0')]:
        out += [f'theorem initial_{name} : bytesT WhileMinImage.initialMem {address} 8 = BitVec.ofNat 64 ({value}) :=',
                f'  (loaderMem_bytes WhileMinImage.pieces WhileMinImage.imageByte {address} 8).trans (by decide +kernel)', '']
    for i in range(1, bins):
        for side, offset in [('forward', 16), ('backward', 24)]:
            out += [f'theorem initial_bin_{i}_{side} :',
                    f'    bytesT WhileMinImage.initialMem (binAt {i} + {offset}) 8 = BitVec.ofNat 64 (binAt {i}) :=',
                    f'  (loaderMem_bytes WhileMinImage.pieces WhileMinImage.imageByte (binAt {i} + {offset}) 8).trans (by decide +kernel)', '']
    def goal(i):
        return (f'bytesT WhileMinImage.initialMem (binAt {i} + 16) 8 = BitVec.ofNat 64 (binAt {i}) ∧\n'
                f'      bytesT WhileMinImage.initialMem (binAt {i} + 24) 8 = BitVec.ofNat 64 (binAt {i})')
    emit_finite_family(out, 'initial_bin_links',
                      [f'⟨initial_bin_{i}_forward, initial_bin_{i}_backward⟩' for i in range(1, bins)],
                      goal, start=1, upper='numBins')
    out += ['end OCaml.Vm.Boot.Startup', '']
    return '\n'.join(out)


if __name__ == '__main__':
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--check', action='store_true')
    args = ap.parse_args()
    path = ROOT / 'OCaml/Vm/Boot/Startup/AllocatorInitialBins.lean'
    text = output()
    if args.check:
        if not path.exists() or path.read_text() != text:
            raise SystemExit('initial allocator bin certificate drift')
    else:
        path.write_text(text)
    print('Initial allocator: 127 empty bins, 256 bounded word certificates')
